local a=require("shell")
local b=require("tty")
local c=require("filesystem")
if b.isAvailable()and io.stdout.tty then
io.write("\27[40m\27[37m")
b.clear()
end
dofile("/etc/motd")
a.setAlias("dir","ls")
a.setAlias("move","mv")
a.setAlias("rename","mv")
a.setAlias("copy","cp")
a.setAlias("del","rm")
a.setAlias("md","mkdir")
a.setAlias("cls","clear")
a.setAlias("rs","redstone")
a.setAlias("view","edit -r")
a.setAlias("help","man")
a.setAlias("l","ls -lhp")
a.setAlias("..","cd ..")
a.setAlias("df","df -h")
a.setAlias("grep","grep --color")
a.setAlias("more","less --noback")
a.setAlias("reset","resolution `cat /dev/components/by-type/gpu/0/maxResolution`")
os.setenv("EDITOR","/bin/edit")
os.setenv("HISTSIZE","10")
os.setenv("HOME","/home")
os.setenv("IFS"," ")
os.setenv("MANPATH","/usr/man:.")
os.setenv("PAGER","less")
os.setenv("PS1","\27[40m\27[31m$HOSTNAME$HOSTNAME_SEPARATOR$PWD # \27[37m")
os.setenv("LS_COLORS","di=0;36:fi=0:ln=0;33:*.lua=0;32")
a.setWorkingDirectory(os.getenv("HOME"))
local b=a.resolve(".shrc")
if c.exists(b)then
loadfile(a.resolve("source","lua"))(b)
end
